import type { FastifyInstance, FastifyReply, FastifyRequest } from 'fastify';

import { container } from '../../../di/container.js';
import { env } from '../../config/env.js';
import { safeCompare } from '../../security/safe-compare.js';

type IdReq = FastifyRequest<{ Params: { id: string } }>;

const positiveId = (req: IdReq, reply: FastifyReply) => {
  const id = Number(req.params.id);
  if (Number.isInteger(id) && id > 0) return id;
  void reply.code(400).send({ error: 'Invalid id' });
  return null;
};

/**
 * NPC portraits generated by Fotor (GM only), plus the completion webhook Fotor calls.
 * The webhook lives outside /api (no client secret: Fotor cannot send one); its secret is the
 * last path segment, and it only triggers a lookup with our own key, so a forged call does nothing.
 */
export async function portraitRoutes(app: FastifyInstance) {
  const gm = { schema: { tags: ['GM'], security: [{ ApiKeyAuth: [] }] } };

  app.get('/api/gm/portraits/status', app.withGM(gm), async () => ({
    enabled: container.resolve('generateNpcPortrait').enabled,
  }));

  // ── Profiles: the style (every portrait) and one per race ──
  app.get('/api/gm/portrait-profiles', app.withGM(gm), async () =>
    container.resolve('listPortraitProfiles').execute(),
  );

  app.put(
    '/api/gm/portrait-profiles/:key',
    app.withGM(gm),
    async (req: FastifyRequest<{ Params: { key: string } }>) =>
      container.resolve('savePortraitProfile').execute(req.params.key, req.body),
  );

  app.delete(
    '/api/gm/portrait-profiles/:key',
    app.withGM(gm),
    async (req: FastifyRequest<{ Params: { key: string } }>, reply) => {
      await container.resolve('deletePortraitProfile').execute(req.params.key);
      return reply.code(204).send();
    },
  );

  // ── Per NPC ──
  app.get(
    '/api/gm/npcs/:id/portrait/draft',
    app.withGM(gm),
    async (
      req: FastifyRequest<{ Params: { id: string }; Querystring: { profile?: string } }>,
      reply,
    ) => {
      const id = positiveId(req, reply);
      return id === null
        ? reply
        : container.resolve('draftNpcPortrait').execute(id, req.query.profile || null);
    },
  );

  app.get('/api/gm/npcs/:id/portraits', app.withGM(gm), async (req: IdReq, reply) => {
    const id = positiveId(req, reply);
    return id === null ? reply : container.resolve('listNpcPortraits').execute(id);
  });

  app.post(
    '/api/gm/npcs/:id/portraits',
    // Each call spends Fotor credits.
    app.withGM({ ...gm, config: { rateLimit: { max: 6, timeWindow: 60_000 } } }),
    async (req: IdReq, reply) => {
      const id = positiveId(req, reply);
      if (id === null) return reply;
      const job = await container.resolve('generateNpcPortrait').execute(id, req.body);
      return reply.code(201).send(job);
    },
  );

  app.post('/api/gm/portraits/:id/check', app.withGM(gm), async (req: IdReq, reply) => {
    const id = positiveId(req, reply);
    return id === null ? reply : container.resolve('checkPortraitJob').execute(id);
  });

  app.post('/api/gm/portraits/:id/apply', app.withGM(gm), async (req: IdReq, reply) => {
    const id = positiveId(req, reply);
    if (id === null) return reply;
    await container.resolve('applyPortrait').execute(id);
    return reply.code(204).send();
  });

  app.delete('/api/gm/portraits/:id', app.withGM(gm), async (req: IdReq, reply) => {
    const id = positiveId(req, reply);
    if (id === null) return reply;
    await container.resolve('deletePortraitJob').execute(id);
    return reply.code(204).send();
  });

  // ── Fotor completion webhook ──
  app.post(
    '/hooks/fotor/:secret',
    { schema: { hide: true }, config: { rateLimit: { max: 60, timeWindow: 60_000 } } },
    async (
      req: FastifyRequest<{ Params: { secret: string }; Body: { taskId?: unknown } }>,
      reply,
    ) => {
      if (!env.FOTOR || !safeCompare(req.params.secret, env.FOTOR.webhookSecret))
        return reply.code(404).send({ error: 'Not found' });
      const taskId = req.body?.taskId;
      if (typeof taskId !== 'string' || !/^[\w-]{1,100}$/.test(taskId))
        return reply.code(400).send({ error: 'Missing taskId' });

      // Fotor asks for a quick 200; the work happens after the reply.
      void reply.code(200).send({ ok: true });
      container
        .resolve('completePortraitJob')
        .execute(taskId)
        .then((job) => {
          if (job) req.log.info({ taskId, job: job.id, status: job.status }, '[portraits] webhook');
        })
        .catch((e: Error) => req.log.error({ taskId, err: e }, '[portraits] webhook failed'));
      return reply;
    },
  );
}
